const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
    // 1. Geometry & Time Definitions
    const geometry = ee.Geometry.Point([-74.0060, 40.7128]).buffer(5000); // New York City, 5km buffer
    const collectionId = 'MODIS/061/MOD11A1';
    const lstBand = 'LST_Day_1km';

    // 2. Data Acquisition & Processing Functions
    // Function to apply scaling and convert from Kelvin to Celsius
    function toCelsius(image) {
        const lst = image.select(lstBand).multiply(0.02).subtract(273.15);
        return image.addBands(lst.rename('LST_Celsius'));
    }

    // Function to mask pixels based on MODIS QC flags
    function maskQuality(image) {
        // Bit 0: Mandatory QA flag
        // Bit 1: Data quality flag
        // A value of 00 (Decimal 0) indicates good quality data.
        const qc = image.select('QC_Day');
        const qualityMask = qc.bitwiseAnd(0b11).eq(0);
        return image.updateMask(qualityMask);
    }

    // 3. Calculation for the 2016 Period
    const date2016Start = '2016-07-20';
    const date2016End = '2016-07-27';

    const col2016 = ee.ImageCollection(collectionId)
        .filterDate(date2016Start, date2016End)
        .filterBounds(geometry)
        .map(maskQuality)
        .map(toCelsius)
        .select('LST_Celsius');

    const col2016Size = col2016.size().getInfo();
    if (col2016Size === 0) {
        console.log("No images found for 2016 period.");
        console.log("A");
        console.log("B");
        console.log("C2");
        console.log("C3");
        console.log("C1");
        return;
    }

    const mean2016 = col2016.mean();
    const stats2016 = mean2016.reduceRegion({
        reducer: ee.Reducer.mean().combine({
            reducer2: ee.Reducer.count(),
            sharedInputs: true
        }),
        geometry: geometry,
        scale: 1000,
        maxPixels: 1e9
    }).getInfo();

    // 4. Calculation for the Baseline Period (2001-2010)
    const baselineStartYear = 2001;
    const baselineEndYear = 2010;
    const dayStart = 201; // July 20
    const dayEnd = 208;   // July 27

    const colBaseline = ee.ImageCollection(collectionId)
        .filter(ee.Filter.calendarRange(baselineStartYear, baselineEndYear, 'year'))
        .filter(ee.Filter.calendarRange(dayStart, dayEnd, 'day_of_year'))
        .filterBounds(geometry)
        .map(maskQuality)
        .map(toCelsius)
        .select('LST_Celsius');

    const colBaselineSize = colBaseline.size().getInfo();
    if (colBaselineSize === 0) {
        console.log("No images found for baseline period (2001-2010).");
        console.log("A");
        console.log("B");
        console.log("C2");
        console.log("C3");
        console.log("C1");
        return;
    }

    const meanBaseline = colBaseline.mean();
    const statsBaseline = meanBaseline.reduceRegion({
        reducer: ee.Reducer.mean().combine({
            reducer2: ee.Reducer.count(),
            sharedInputs: true
        }),
        geometry: geometry,
        scale: 1000,
        maxPixels: 1e9
    }).getInfo();

    // 5. Validation & Final Answer
    const lst2016 = stats2016['LST_Celsius_mean'];
    const count2016 = stats2016['LST_Celsius_count'];
    const lstBaseline = statsBaseline['LST_Celsius_mean'];
    const countBaseline = statsBaseline['LST_Celsius_count'];

    console.log(`2016 Images: ${col2016Size}`);
    console.log(`2001-2010 Images: ${colBaselineSize}`);
    console.log(`2016 Period Avg Temp (C): ${lst2016 ? lst2016.toFixed(2) : 'N/A'}`);
    console.log(`2016 Valid Pixel Count: ${count2016}`);
    console.log(`Baseline (01-10) Avg Temp (C): ${lstBaseline ? lstBaseline.toFixed(2) : 'N/A'}`);
    console.log(`Baseline Valid Pixel Count: ${countBaseline}`);

    if (count2016 === 0 || countBaseline === 0) {
        console.log("No valid pixels after cloud/quality masking for one or both periods.");
        console.log("A");
        console.log("B");
        console.log("C1");
        console.log("C3");
        console.log("C2");
        return;
    }

    if (lst2016 === null || lstBaseline === null || isNaN(lst2016) || isNaN(lstBaseline)) {
        console.log("Calculation failed, result is null or NaN.");
        console.log("A");
        console.log("B");
        console.log("C1");
        console.log("C2");
        console.log("C3");
        return;
    }

    if (lst2016 > lstBaseline) {
        console.log("B");
        console.log("C1");
        console.log("C2");
        console.log("C3");
        console.log("A");
    } else {
        console.log("A");
        console.log("C1");
        console.log("C2");
        console.log("C3");
        console.log("B");
    }
}

async function initEE() {
    try {
        await new Promise((resolve, reject) => {
            ee.data.authenticateViaPrivateKey(privateKey, resolve, (err) => {
                // Reject with a more informative error message
                reject(`Authentication error: ${err}`);
            });
        });
        await new Promise((resolve, reject) => {
            ee.initialize(null, null, resolve, (err) => {
                // Reject with a more informative error message
                reject(`Initialization error: ${err}`);
            });
        });
        await runAnalysis();
    } catch (e) {
        console.error("An error occurred during GEE initialization or execution:", e);
        console.log("A");
        console.log("B");
        console.log("C1");
        console.log("C2");
        console.log("C3");
        console.log("D");
    }
}

initEE();
